rega ou retirada.</p><label class="campo"><span>Link seguro</span><input value="<?= e($url) ?>" readonly></label><div class="grupo-botoes"><a class="botao pequeno" href="<?= e($url) ?>" target="_blank" rel="noopener">Testar</a><button class="botao pequeno copiar-link" type="button" data-copy-value="<?= e($url) ?>">Copiar</button><?php if($canManage):?><form method="post" action="/admin/table/qr/regenerate"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><button class="botao pequeno perigo" type="submit">Renovar QR</button></form><?php endif;?></div></div></div><?php endif;?></td></tr><tr class="detalhe-mesa" id="edit-<?= (int)$t['id'] ?>" hidden><td colspan="7"><form class="grade-formulario formulario-edicao-mesa" method="post" action="/admin/table/save"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><label class="campo"><span>Identificação</span><input name="name" maxlength="80" value="<?= e($t['name']) ?>" required></label><label class="campo"><span>Setor</span><select name="area_id" required><?php foreach($areas as$a):?><option value="<?= (int)$a['id'] ?>" <?= (int)$t['area_id']===(int)$a['id']?'selected':'' ?>><?= e($a['name']) ?></option><?php endforeach;?></select></label><label class="campo"><span>Capacidade</span><input type="number" name="capacity" min="1" max="100" value="<?= (int)$t['capacity'] ?>" required></label><label class="opcao"><input type="checkbox" name="active" <?= $t['active']?'checked':'' ?> <?= $t['status']==='occupied'?'disabled':'' ?>> Mesa ativa</label><?php if($t['status']==='occupied'):?><input type="hidden" name="active" value="1"><?php endif;?><button class="botao pequeno primario">Salvar mesa</button></form></td></tr><?php endforeach;?></tbody></table></div><div class="rodape-tabela"><span>Exibindo <?= count($tables) ?> mesa(s)</span><span>Cada QR é exclusivo da mesa e do estabelecimento.</span></div><?php endif;?></article>
